def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    for i in range(len(grid)):
        if i % 2 == 0:
            # Even row: left to right
            for j in range(len(grid[i])):
                if j % 2 == 0:
                    result.append(grid[i][j])
        else:
            # Odd row: right to left
            for j in range(len(grid[i]) - 1, -1, -1):
                if j % 2 == 1:
                    result.append(grid[i][j])
    return result

from collections import Counter

def findValidPair(s: str) -> str:
    count = Counter(s)
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:  # Check if adjacent digits are different
            first_digit = int(s[i])
            second_digit = int(s[i + 1])
            if count[s[i]] == first_digit and count[s[i + 1]] == second_digit:
                return s[i:i + 2]  # Return the first valid pair found
    return ""  # Return an empty string if no valid pair is found

