def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    if n < 2:
        return n
    # Create a DP array to store the length of the longest subsequence ending at each index
    dp = [0] * n
    maxLength = 0

    # Iterate through each element to build the DP solution
    for i in range(n):
        for j in range(i):
            if abs(nums[j] - nums[i]) > 0:
                diff = abs(nums[i] - nums[j])
                current_length = 2
                last_diff = diff
                # For each element before j, maintain the conditions for non-increasing absolute differences
                for k in range(j):
                    if abs(nums[j] - nums[k]) <= last_diff:
                        current_length += 1
                        last_diff = abs(nums[j] - nums[k])

                dp[i] = max(dp[i], current_length)
                maxLength = max(maxLength, dp[i])

    return maxLength

