def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    # Create a 3D DP array to track maximum coins with 0, 1, or 2 neutralizations
    dp = [[[-float('inf')] * 3 for _ in range(n + 1)] for _ in range(m + 1)]
    dp[1][1][0] = coins[0][0]  # Starting point, starting at cell (0,0) with its value

    for i in range(m):
        for j in range(n):
            coin = coins[i][j]
            for used in range(3):  # 0, 1, or 2 neutralizations used
                if coin >= 0:
                    # If non-negative, add it without neutralization
                    dp[i + 1][j + 1][used] = max(dp[i + 1][j + 1][used], dp[i][j][used] + coin, dp[i + 1][j][used] + coin)
                else:
                    # If the coin is negative, we potentially lose coins
                    # Use neutralization if we have left
                    if used < 2:
                        dp[i + 1][j + 1][used + 1] = max(dp[i + 1][j + 1][used + 1], dp[i][j][used], dp[i + 1][j][used])
                    # Continuing without neutralization
                    dp[i + 1][j + 1][used] = max(dp[i + 1][j + 1][used], dp[i][j][used] + coin, dp[i + 1][j][used] + coin)

    # Return the maximum coins possible with up to 2 neutralizations
    return max(dp[m][n])  # Return maximum coins (allowing negative outcomes)

