def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_until = [0] * numberOfUsers

    for event in events:
        event_type, timestamp, *args = event
        timestamp = int(timestamp)

        if event_type == "OFFLINE":
            user_id = int(args[0])  # directly convert to int
            online_status[user_id] = False
            offline_until[user_id] = timestamp + 60

        elif event_type == "MESSAGE":
            # Update online status before processing message
            for i in range(numberOfUsers):
                if timestamp >= offline_until[i]:
                    online_status[i] = True

            mentions_string = args[0]
            user_ids = mentions_string.split()
            for user_id in user_ids:
                if user_id == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif user_id == "HERE":
                    for i in range(numberOfUsers):
                        if online_status[i]:
                            mentions[i] += 1
                else:
                    user_id_num = int(user_id[2:])  # remove 'id'
                    mentions[user_id_num] += 1

    return mentions

